int Result{};
void Fail(const char *message) { if (!Result) { std::cerr << message << '\n'; Result = 1; } }
void Hash(std::uint64_t &hash, std::uint64_t value) { for (unsigned byte=0;byte<8;++byte){hash^=(value>>(byte*8))&0xffu;hash*=1099511628211ull;} }
bool NormalValidationRun(){wchar_t expected[8]{};const DWORD count=GetEnvironmentVariableW(L"AEVRYND_EXPECT_GPU_VALIDATION_MODE",expected,DWORD(std::size(expected)));return count==6&&lstrcmpW(expected,L"normal")==0;}
bool Validation(const RendererStats& stats){wchar_t expected[8]{};const DWORD count=GetEnvironmentVariableW(L"AEVRYND_EXPECT_GPU_VALIDATION_MODE",expected,DWORD(std::size(expected)));if(count==6&&lstrcmpW(expected,L"normal")==0)return!stats.gpuValidationRequested&&!stats.gpuValidationAvailable&&!stats.gpuValidationExecuted&&!stats.debugLayerEnabled&&!stats.gpuValidationPassed&&!stats.debugErrorCount&&!stats.debugWarningCount;if(count==3&&lstrcmpW(expected,L"gbv")==0)return stats.gpuValidationRequested&&stats.gpuValidationAvailable&&stats.gpuValidationExecuted&&stats.debugLayerEnabled&&stats.gpuValidationPassed&&!stats.debugErrorCount&&!stats.debugWarningCount;return false;}

MaterialAssetDefinition3D Material(){MaterialAssetDefinition3D value;value.textures={"engine/assets/material-packs/ambientcg/ground037/1k/Ground037_1K-JPG_Color.jpg","engine/assets/material-packs/ambientcg/ground037/1k/Ground037_1K-JPG_Roughness.jpg",64,"engine/assets/material-packs/ambientcg/ground037/1k/Ground037_1K-JPG_NormalDX.jpg"};value.material.useUv=true;return value;}
StaticMeshAssetDefinition3D Asset(std::string name,std::filesystem::path path){StaticMeshAssetDefinition3D value;value.name=std::move(name);value.meshPath=std::move(path);value.material=Material();value.generateLods=false;return value;}

class FakeReceiptSource final:public IGpuRetirementReceiptSource3D{
public:
 GpuRetirementReceipt3D CaptureGraphicsRetirementReceipt3D()override{return failCapture?GpuRetirementReceipt3D{}:MakeReceipt(17,next_++);}
 bool IsGraphicsRetirementComplete3D(GpuRetirementReceipt3D receipt)const override{return autoComplete||completed_.contains(receipt.FenceValue());}
 void CompleteAll(){for(std::uint64_t value=1;value<next_;++value)completed_.insert(value);}
 bool failCapture{},autoComplete{};
private:std::uint64_t next_{1};std::unordered_set<std::uint64_t> completed_{};
};

struct Fixture{std::shared_ptr<TerrainVegetationChunkPayload3D> payload{};std::string proxyName{};};
Fixture MakeFixture(StaticMeshAssetLibrary3D& library,TerrainVegetationChunkSettings3D settings,GlobalChunkCoordinate3D chunk,HlodClusterId3D clusterId,std::uint64_t generation,std::uint64_t serial,HlodCompatibility3D compatibility=HlodCompatibility3D::OpaqueCompatible,std::size_t reservedOverride=SIZE_MAX,std::string sourceName="hlod-source",float manifestOffset=0.f){
 auto proxy=library.PrepareHlodProxyCpu3D(settings.worldId,chunk,clusterId,generation,Asset({},"engine/assets/model-packs/poly-haven/rock_09/rock_09.aemesh"));if(!proxy)return{};
 const std::array<HlodSourceBuildInput3D,2> sources{{{{{serial,serial+1}},serial+10,1,1,1,1,{},{1,1,1},{-2,0,0},{},{1,1,1}},{{{serial,serial+2}},serial+11,1,1,1,1,{},{1,1,1},{2,0,0},{},{1,1,1}}}};
 HlodClusterBuildInput3D cluster{};cluster.asset={clusterId,generation,{},5,1,.8f,1.2f,2,compatibility};cluster.resource={1,1,proxy->reservedPhysicalBytes,1,1,100,20};cluster.instance={clusterId,chunk,{},{1,1,1},{}};cluster.sources=sources;const std::array clusters{cluster};auto data=BuildHlodData3D(clusters);if(!data)return{};
 std::array<TerrainVegetationHlodSource3D,2> manifestSources{{{sources[0].reference,sources[0].generation,sourceName,{chunk,{-2+manifestOffset,0,0}},{},{1,1,1}},{sources[1].reference,sources[1].generation,sourceName,{chunk,{2,0,0}},{},{1,1,1}}}};
 if(reservedOverride!=SIZE_MAX)proxy->reservedPhysicalBytes=reservedOverride;
 TerrainVegetationHlodCluster3D manifestCluster{};manifestCluster.id=clusterId;manifestCluster.generation=generation;manifestCluster.proxy=*proxy;manifestCluster.sources.assign(manifestSources.begin(),manifestSources.end());const std::array manifestClusters{manifestCluster};auto manifest=BuildTerrainVegetationHlodManifest3D(manifestClusters,*data);if(!manifest)return{};
 auto payload=std::make_shared<TerrainVegetationChunkPayload3D>();payload->globalChunk=chunk;HeightField3D field({{},5,5,2});field.Generate(static_cast<std::uint32_t>(serial),1,.05f,2);payload->heightField=field;payload->terrain=field.CreateMesh();payload->hlod=std::move(data);payload->hlodManifest=std::move(manifest);payload->cpuBytes=payload->terrain.vertices.size()*sizeof(Vertex3D)+payload->terrain.indices.size()*sizeof(std::uint32_t);return{std::move(payload),proxy->logicalName};
}
WorldChunkPayload3D Opaque(const Fixture& fixture){return{fixture.payload,fixture.payload->cpuBytes,fixture.payload->cpuBytes};}

Fixture MakeMultiClusterFixture(StaticMeshAssetLibrary3D& library,TerrainVegetationChunkSettings3D settings,GlobalChunkCoordinate3D chunk){
 std::array<std::array<HlodSourceBuildInput3D,2>,2> sourceStorage{};std::array<HlodClusterBuildInput3D,2> build{};std::array<TerrainVegetationHlodCluster3D,2> manifest{};
 for(std::size_t index=0;index<2;++index){const HlodClusterId3D id{800+index,900};auto proxy=library.PrepareHlodProxyCpu3D(settings.worldId,chunk,id,1,Asset({},"engine/assets/model-packs/poly-haven/rock_09/rock_09.aemesh"));if(!proxy)return{};const std::uint64_t base=9000+index*10;sourceStorage[index]={{{{{base,base+1}},base+2,1,1,1,1,{},{1,1,1},{-2,0,0},{},{1,1,1}},{{{base+3,base+4}},base+5,1,1,1,1,{},{1,1,1},{2,0,0},{},{1,1,1}}}};build[index].asset={id,1,{},5,1,.8f,1.2f,2,HlodCompatibility3D::OpaqueCompatible};build[index].resource={1,1,proxy->reservedPhysicalBytes,1,1,100,20};build[index].instance={id,chunk,{float(index)*3,0,0},{1,1,1},{}};build[index].sources=sourceStorage[index];manifest[index].id=id;manifest[index].generation=1;manifest[index].proxy=*proxy;manifest[index].sources={{{{base,base+1}},base+2,"hlod-source",{chunk,{-2+float(index)*3,0,0}},{},{1,1,1}},{{{base+3,base+4}},base+5,"hlod-source",{chunk,{2+float(index)*3,0,0}},{},{1,1,1}}};}
 auto data=BuildHlodData3D(build);if(!data)return{};auto immutableManifest=BuildTerrainVegetationHlodManifest3D(manifest,*data);if(!immutableManifest)return{};auto payload=std::make_shared<TerrainVegetationChunkPayload3D>();payload->globalChunk=chunk;HeightField3D field({{},5,5,2});field.Generate(81,1,.05f,2);payload->heightField=field;payload->terrain=field.CreateMesh();payload->hlod=std::move(data);payload->hlodManifest=std::move(immutableManifest);payload->cpuBytes=payload->terrain.vertices.size()*sizeof(Vertex3D)+payload->terrain.indices.size()*sizeof(std::uint32_t);return{std::move(payload),{}};
}

std::uint64_t CanonicalHash(Engine& engine,SceneECSRegistry3D& scene,ChunkedVegetationWorld3D& vegetation,StaticMeshAssetLibrary3D& library,TerrainVegetationWorldChunkActivationTarget3D& target){
 std::uint64_t hash=1469598103934665603ull;Scene3D collected;DrawList draw;const auto s=scene.Collect(collected,draw);const auto r=engine.GetRendererStats();const auto v=vegetation.Stats();const auto l=library.Stats();const auto h=target.HlodStats();
 Hash(hash,s.aliveEntities);Hash(hash,s.transformComponents);Hash(hash,s.renderableComponents);Hash(hash,s.submittedRenderables);Hash(hash,s.hidden);Hash(hash,r.residentMeshBytes);Hash(hash,r.residentMeshResources);Hash(hash,r.residentMaterialTextureSets);Hash(hash,r.residentMaterialTextureReferences);Hash(hash,r.residentTextureAllocationBytes);Hash(hash,r.pendingGpuReleaseBytes);Hash(hash,v.chunks);Hash(hash,v.instances);Hash(hash,l.assets);Hash(hash,l.materialReferences);Hash(hash,l.meshLevels);Hash(hash,l.liveInstances);Hash(hash,l.assetBorrowers);Hash(hash,h.attachedClusters);Hash(hash,h.residentSourceEntities);Hash(hash,h.residentProxyEntities);Hash(hash,h.retiringClusters);Hash(hash,h.aliasBytes);Hash(hash,h.proxyReservedBytes);Hash(hash,h.proxyActualResidentBytes);Hash(hash,h.retiringProxyBytes);Hash(hash,h.pendingRetirementReceipts);Hash(hash,target.PendingRetirements());return hash;
}
std::size_t RetainedCapacity(SceneECSRegistry3D& scene,ChunkedVegetationWorld3D& vegetation,TerrainVegetationWorldChunkActivationTarget3D& target){return scene.MemoryStats().retainedCapacityBytes+vegetation.MemoryStats().retainedCapacityBytes+target.HlodStats().metadataCapacityBytes;}

